def create_initial_template_revisions(apps, schema_editor):
    Campaign = apps.get_model("rasel", "Campaign")
    CampaignMessage = apps.get_model("rasel", "CampaignMessage")
    MessageTemplate = apps.get_model("rasel", "MessageTemplate")
    MessageTemplateRevision = apps.get_model(
        "messaging", "MessageTemplateRevision"
    )

    for template in MessageTemplate.objects.all().iterator():
        approved_at = template.approved_at
        approved_by_id = template.approved_by_id
        if template.approval_status == "approved":
            approved_at = approved_at or template.updated_at or timezone.now()
            approved_by_id = approved_by_id or template.created_by_id
        revision = MessageTemplateRevision.objects.create(
            organization_id=template.organization_id,
            template_id=template.pk,
            version=1,
            content=template.content,
            approval_status=template.approval_status,
            created_by_id=template.created_by_id,
            approved_by_id=approved_by_id,
            approved_at=approved_at,
            is_current=True,
        )
        template.current_revision_id = revision.pk
        template.save(update_fields=("current_revision",))
        Campaign.objects.filter(template_id=template.pk).update(
            template_revision_id=revision.pk
        )
        CampaignMessage.objects.filter(template_id=template.pk).update(
            template_revision_id=revision.pk
        )

    CampaignMessage.objects.filter(status="sent").update(
        status="operator_marked_sent"
    )


def remove_initial_template_revisions(apps, schema_editor):
    Campaign = apps.get_model("rasel", "Campaign")
