    MessageTemplateRevision = apps.get_model(
        "messaging", "MessageTemplateRevision"
    )

    CampaignMessage.objects.filter(status="operator_marked_sent").update(
        status="sent"
    )
    Campaign.objects.update(template_revision=None)
    CampaignMessage.objects.update(template_revision=None)
    MessageTemplate.objects.update(current_revision=None)
    MessageTemplateRevision.objects.all().delete()


